using catalog::CatalogStationEdge;
using catalog::StationCatalog;
using dispatcher::ResourceTable;

struct NodeCoord {
  double x, y, yaw;
};

std::optional<NodeCoord> FindNodeCoord(const StationCatalog& catalog, const std::string& id) {
  if (const auto* station = catalog::FindStation(catalog, id)) {
    return NodeCoord{station->x, station->y, station->yaw};
  }
  for (const auto& node : catalog.road_nodes) {
    if (node.id == id) return NodeCoord{node.x, node.y, node.yaw};
  }
  return std::nullopt;
}

const CatalogStationEdge* FindCatalogEdge(const StationCatalog& catalog, const std::string& from, const std::string& to) {
  for (const auto& edge : catalog.edges) {
    if (edge.from == from && edge.to == to) return &edge;
    if (edge.bidirectional && edge.from == to && edge.to == from) return &edge;
  }
  return nullptr;
}

double SegmentYaw(const std::vector<std::pair<double,double>>& pts, size_t i) {
  if (pts.size() < 2) return 0.0;
  size_t j = (i + 1 < pts.size()) ? i + 1 : i - 1;
  return std::atan2(pts[j].second - pts[i].second, pts[j].first - pts[i].first);
}

std::vector<VehicleTrajectoryPoint> PolylineToTrajectory(
    const std::vector<std::pair<double,double>>& pts) {
  std::vector<VehicleTrajectoryPoint> traj;
  traj.reserve(pts.size());
  for (size_t i = 0; i < pts.size(); ++i) {
    traj.push_back({pts[i].first, pts[i].second, SegmentYaw(pts, i)});
  }
  return traj;
}

}  // namespace
