    const bool edge_locked = reserved_locks.count(edge.edge_id) > 0;
    const bool both_nodes_released = order.nodes[i].released && order.nodes[i + 1].released;
    const bool horizon_started = i > 0 && !order.edges[i - 1].released;
    edge.released = edge_locked && both_nodes_released && !horizon_started;

